                continue
            full_path = str(path.resolve())
            metadata = path.stat()
            last = max(0, metadata.st_size - 64)
            with path.open('rb') as stream:
                samples = []
                for offset in (0, last // 2, last):
                    stream.seek(offset)
                    samples.append(stream.read(64))
